-- seed_perf_g1_math_u1.sql — 수행과제 카드 7건 적재 (perf_cards_to_seed.py 산출, 재실행 안전: code UNIQUE UPSERT)
-- 선행: setup_worksheet_v4.sql (performance_tasks)
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_01',1,'math','u1','조사·탐구 (+ 문제해결 과정)','우리 교실 수 찾기','교실 탐험 — 수를 찾아라!','우리 교실에서 1개, 2개, 3개… 9개까지, 개수가 다른 물건을 찾아보세요. 찾은 물건을 사진 찍거나 그림으로 그리고, 몇 개인지 말해 보세요.',ARRAY['서로 다른 수의 물건을 3가지 이상 찾기','각 물건의 수를 숫자로 쓰고 말로 읽기 (예: 4, 넷)','찾은 것 중 가장 많은 것이 무엇인지 말하기']::text[],'{"criteria": [{"name": "수 세기 정확성", "levels": [{"label": "잘함", "desc": "찾은 물건 모두 정확히 센다"}, {"label": "보통", "desc": "1~2개 물건에서 세기 오류"}, {"label": "노력 요함", "desc": "세기 오류가 잦고 도움 필요"}]}, {"name": "수 표현 (읽기·쓰기)", "levels": [{"label": "잘함", "desc": "숫자·읽는 말 모두 바르다"}, {"label": "보통", "desc": "쓰기 또는 읽기 한쪽에서 실수"}, {"label": "노력 요함", "desc": "숫자·말 연결이 아직 어렵다"}]}, {"name": "비교·설명", "levels": [{"label": "잘함", "desc": "가장 많은 것을 근거와 함께 말한다"}, {"label": "보통", "desc": "가장 많은 것을 고르나 근거가 약하다"}, {"label": "노력 요함", "desc": "비교 설명이 어렵다"}]}]}'::jsonb,'{"잘함": "\"지우개 3개, 창문 4개, 사물함 9개를 찾았어요. 사물함이 아홉 개로 제일 많아요. 하나씩 짚으면서 세었어요.\"", "보통": "\"연필 5개, 의자 4개 찾았어요. (읽기에서 ''오''를 ''다섯''과 혼동) 의자가... 많아요?\" — 세기는 맞으나 표현·근거 흔들림", "노력 요함": "물건은 찾았으나 개수를 어른이 함께 세어야 함, 숫자 쓰기에 도움 필요"}'::jsonb,'[{"text": "하나씩 짚으며 세는가, 눈대중인가", "mis_code": "M01", "note": null}, {"text": "마지막 센 수를 전체 개수로 말하는가", "mis_code": "M03", "note": null}, {"text": "''많다''를 개수로 판단하는가, 크기로 판단하는가", "mis_code": "M10", "note": null}]'::jsonb,'[2수01-01] 수 세기·읽기·쓰기, [2수01-02] 수의 크기 비교','1~2차시(수 세기) 이후, 7차시(비교) 전후 재사용 가능',NULL,'photo','kedu')
  ON CONFLICT (code) DO UPDATE SET grade=EXCLUDED.grade, subject=EXCLUDED.subject, unit_code=EXCLUDED.unit_code, area=EXCLUDED.area, title=EXCLUDED.title, student_label=EXCLUDED.student_label, task_text=EXCLUDED.task_text, conditions=EXCLUDED.conditions, rubric=EXCLUDED.rubric, anchors=EXCLUDED.anchors, observe_points=EXCLUDED.observe_points, std_code=EXCLUDED.std_code, lesson_link=EXCLUDED.lesson_link, concept_code=EXCLUDED.concept_code, product_kind=EXCLUDED.product_kind, source=EXCLUDED.source, is_active=true;
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_02',1,'math','u1','만들기·표현','나만의 수 카드 만들기','수 카드 공장 — 여섯부터 아홉까지','6, 7, 8, 9 중에서 좋아하는 수를 두 개 골라 수 카드를 만들어요. 카드 앞면에는 숫자를, 뒷면에는 그 개수만큼 그림을 그려요. 다 만들면 카드를 보여 주며 "이건 여덟, 여덟 개예요"처럼 말해 보세요.',ARRAY['6~9 중 서로 다른 수 두 개 고르기','뒷면 그림 개수와 앞면 숫자가 꼭 같게 그리기','카드마다 숫자와 읽는 말을 모두 말하기 (예: 8, 여덟)']::text[],'{"criteria": [{"name": "수량-숫자 대응", "levels": [{"label": "잘함", "desc": "두 카드 모두 그림 수와 숫자가 정확히 맞다"}, {"label": "보통", "desc": "한 카드에서 1개 차이가 난다"}, {"label": "노력 요함", "desc": "그림 수와 숫자가 자주 어긋난다"}]}, {"name": "수 읽기·쓰기", "levels": [{"label": "잘함", "desc": "숫자 모양이 바르고 읽는 말도 정확하다"}, {"label": "보통", "desc": "숫자는 쓰나 읽는 말이 흔들린다"}, {"label": "노력 요함", "desc": "숫자 쓰기·읽기에 도움이 필요하다"}]}, {"name": "설명하기", "levels": [{"label": "잘함", "desc": "카드를 보이며 개수와 이름을 또렷이 말한다"}, {"label": "보통", "desc": "물으면 답하지만 스스로 설명은 짧다"}, {"label": "노력 요함", "desc": "설명이 어렵고 되묻는 도움이 필요하다"}]}]}'::jsonb,'{"잘함": "7 카드 뒷면에 사과 7개, 9 카드 뒷면에 별 9개. \"이건 일곱이에요. 사과가 일곱 개예요. 이건 아홉, 별이 아홉 개예요.\" 그리면서 하나씩 짚어 셈.", "보통": "6 카드 뒷면에 동그라미 6개(정확), 8 카드 뒷면에 7개만 그림. \"여덟이요… (읽기에서 ''팔''과 ''여덟''을 섞어 말함)\"", "노력 요함": "숫자 9를 거울처럼 뒤집어 씀. 그림은 그렸으나 개수를 교사와 함께 세어야 확인됨."}'::jsonb,'[{"text": "그림을 하나씩 짚으며 세는가, 눈대중으로 그리는가", "mis_code": "M01", "note": null}, {"text": "개수는 하나·둘…, 번호는 일·이… 로 상황에 맞게 읽는가", "mis_code": "M02", "note": null}, {"text": "다 그린 뒤 \"그래서 모두 몇 개?\"에 마지막 센 수로 답하는가", "mis_code": "M03", "note": null}]'::jsonb,'[2수01-01] 수 세기·읽기·쓰기','2차시(6~9의 수) 직후','M1-1-C2','photo','kedu')
  ON CONFLICT (code) DO UPDATE SET grade=EXCLUDED.grade, subject=EXCLUDED.subject, unit_code=EXCLUDED.unit_code, area=EXCLUDED.area, title=EXCLUDED.title, student_label=EXCLUDED.student_label, task_text=EXCLUDED.task_text, conditions=EXCLUDED.conditions, rubric=EXCLUDED.rubric, anchors=EXCLUDED.anchors, observe_points=EXCLUDED.observe_points, std_code=EXCLUDED.std_code, lesson_link=EXCLUDED.lesson_link, concept_code=EXCLUDED.concept_code, product_kind=EXCLUDED.product_kind, source=EXCLUDED.source, is_active=true;
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_03',1,'math','u1','발표·말하기','우리 줄, 내가 몇째?','줄서기 방송국 — 몇째인지 말해요','친구들 5~9명이 한 줄로 섰어요. 앞에서부터 세어 내가 몇째인지, 그리고 내 앞뒤 친구가 몇째인지 말해 보세요. 이번엔 뒤에서부터 세면 내가 몇째가 되는지도 말해 보세요.',ARRAY['어디에서부터 세는지 방향을 먼저 말하기 (예: "앞에서부터 세면")','나·앞 친구·뒤 친구 세 사람의 자리를 몇째로 말하기','마지막에 줄에 선 사람은 모두 몇 명인지 말하기']::text[],'{"criteria": [{"name": "순서수 사용", "levels": [{"label": "잘함", "desc": "셋째·넷째처럼 순서를 나타내는 말을 바르게 쓴다"}, {"label": "보통", "desc": "대체로 맞지만 한두 번 \"3개\"처럼 개수 말로 바뀐다"}, {"label": "노력 요함", "desc": "순서 말과 개수 말이 자주 섞인다"}]}, {"name": "기준 방향", "levels": [{"label": "잘함", "desc": "세는 방향을 먼저 밝히고 끝까지 지킨다"}, {"label": "보통", "desc": "방향은 말하나 도중에 바뀐다"}, {"label": "노력 요함", "desc": "방향을 밝히지 않고 아무 쪽에서 센다"}]}, {"name": "순서와 개수 구분", "levels": [{"label": "잘함", "desc": "몇째(자리)와 몇 명(전체)을 구분해 말한다"}, {"label": "보통", "desc": "물어보면 구분하나 스스로는 섞는다"}, {"label": "노력 요함", "desc": "둘의 차이를 아직 말하지 못한다"}]}]}'::jsonb,'{"잘함": "\"앞에서부터 세면 저는 넷째예요. 제 앞은 셋째, 제 뒤는 다섯째예요. 뒤에서부터 세면 저는 셋째가 돼요. 줄에는 모두 여섯 명이에요.\"", "보통": "\"저는 넷째요. 앞에는 셋째… 뒤는 5개요.\" — 순서수를 대체로 쓰나 마지막에 개수 말로 바뀜.", "노력 요함": "\"저는 4요.\" 방향을 밝히지 않고, 다시 물으면 반대쪽에서 세어 답이 달라짐."}'::jsonb,'[{"text": "\"셋째\"와 \"3개\"를 구분해 쓰는가", "mis_code": "M04", "note": null}, {"text": "세는 기준 방향을 스스로 정하고 유지하는가", "mis_code": "M05", "note": null}, {"text": "줄 전체 인원을 마지막 센 수로 답하는가", "mis_code": "M03", "note": null}]'::jsonb,'[2수01-02] 수의 순서','3차시(순서수 — 몇째) 직후','M1-1-C3','text','kedu')
  ON CONFLICT (code) DO UPDATE SET grade=EXCLUDED.grade, subject=EXCLUDED.subject, unit_code=EXCLUDED.unit_code, area=EXCLUDED.area, title=EXCLUDED.title, student_label=EXCLUDED.student_label, task_text=EXCLUDED.task_text, conditions=EXCLUDED.conditions, rubric=EXCLUDED.rubric, anchors=EXCLUDED.anchors, observe_points=EXCLUDED.observe_points, std_code=EXCLUDED.std_code, lesson_link=EXCLUDED.lesson_link, concept_code=EXCLUDED.concept_code, product_kind=EXCLUDED.product_kind, source=EXCLUDED.source, is_active=true;
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_04',1,'math','u1','조사·탐구','1부터 9까지 수 줄 만들기','수 줄 탐험대 — 순서대로 놓아요','교실이나 집에서 물건을 모아 1개짜리부터 9개짜리까지 순서대로 늘어놓아요. 다 놓았으면 앞에서부터 1, 2, 3… 9까지 이어 세고, 이번엔 9부터 거꾸로 세어 보세요.',ARRAY['1부터 9까지 빠짐없이 자리를 채우기 (같은 물건이어도 됨)','이어 세기와 거꾸로 세기를 한 번씩 소리 내어 하기','비어 있는 자리를 하나 만들어 두고, 그 자리에 올 수를 말하기']::text[],'{"criteria": [{"name": "순서 배열", "levels": [{"label": "잘함", "desc": "1~9를 빠짐·중복 없이 순서대로 놓는다"}, {"label": "보통", "desc": "한 자리 정도 순서가 어긋난다"}, {"label": "노력 요함", "desc": "여러 자리가 뒤섞여 도움이 필요하다"}]}, {"name": "이어 세기·거꾸로 세기", "levels": [{"label": "잘함", "desc": "두 방향 모두 막힘없이 센다"}, {"label": "보통", "desc": "이어 세기는 되나 거꾸로 세기에서 멈칫한다"}, {"label": "노력 요함", "desc": "두 방향 모두 함께 세어야 한다"}]}, {"name": "빈자리 추론", "levels": [{"label": "잘함", "desc": "앞뒤 수를 근거로 빠진 수를 말한다"}, {"label": "보통", "desc": "빠진 수는 맞히나 근거를 말하지 못한다"}, {"label": "노력 요함", "desc": "처음부터 다시 세어야 찾는다"}]}]}'::jsonb,'{"잘함": "지우개 1, 연필 2 … 블록 9까지 줄을 세움. \"일, 이, 삼… 아홉. 아홉, 여덟, 일곱… 하나. 여기 빈자리는 여섯이에요. 앞이 다섯이고 뒤가 일곱이니까요.\"", "보통": "1~9를 놓았으나 6과 7의 자리가 바뀜. 이어 세기는 정확, 거꾸로 세기는 \"여섯… 어… 다섯\"에서 한 번 멈춤. 빈자리는 맞히지만 \"그냥 알아요\"라고 답함.", "노력 요함": "물건은 모았으나 4 다음에 6을 놓는 등 자리를 여러 곳 건너뜀. 거꾸로 세기는 교사와 함께 진행."}'::jsonb,'[{"text": "이어 세기·거꾸로 세기에서 순서가 흐트러지는 지점이 어디인가", "mis_code": "M06", "note": null}, {"text": "각 자리에 놓은 물건 수를 하나씩 짚어 확인하는가", "mis_code": "M01", "note": null}, {"text": "빈자리를 앞뒤 수(1만큼 큰/작은)로 설명하는가", "mis_code": "M07", "note": null}]'::jsonb,'[2수01-02] 수의 순서','4차시(수의 순서 — 이어 세기·거꾸로 세기) 직후','M1-1-C4','photo','kedu')
  ON CONFLICT (code) DO UPDATE SET grade=EXCLUDED.grade, subject=EXCLUDED.subject, unit_code=EXCLUDED.unit_code, area=EXCLUDED.area, title=EXCLUDED.title, student_label=EXCLUDED.student_label, task_text=EXCLUDED.task_text, conditions=EXCLUDED.conditions, rubric=EXCLUDED.rubric, anchors=EXCLUDED.anchors, observe_points=EXCLUDED.observe_points, std_code=EXCLUDED.std_code, lesson_link=EXCLUDED.lesson_link, concept_code=EXCLUDED.concept_code, product_kind=EXCLUDED.product_kind, source=EXCLUDED.source, is_active=true;
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_05',1,'math','u1','문제해결 과정','하나 더, 하나 덜 이야기','하나 더 하나 덜 — 어떻게 알았는지 말해요','접시에 사탕이 몇 개 있어요. 친구가 하나를 더 주면 몇 개가 될까요? 반대로 하나를 먹으면 몇 개가 남을까요? 답만 말하지 말고, 어떻게 알았는지 그림이나 수 배열판으로 보여 주며 말해 보세요.',ARRAY['시작하는 수를 3~8 중에서 스스로 골라 정하기','1만큼 더 큰 수와 1만큼 작은 수를 둘 다 구하기','답을 구한 방법을 "왜냐하면 ~"으로 한 문장 말하기']::text[],'{"criteria": [{"name": "답의 정확성", "levels": [{"label": "잘함", "desc": "더 큰 수·작은 수를 모두 정확히 구한다"}, {"label": "보통", "desc": "한쪽만 정확하다"}, {"label": "노력 요함", "desc": "두 답 모두 흔들린다"}]}, {"name": "방향 이해", "levels": [{"label": "잘함", "desc": "더 큰 쪽·작은 쪽을 배열판에서 바르게 가리킨다"}, {"label": "보통", "desc": "대체로 맞으나 한 번 방향이 바뀐다"}, {"label": "노력 요함", "desc": "커지는 쪽과 작아지는 쪽을 반대로 잡는다"}]}, {"name": "과정 설명", "levels": [{"label": "잘함", "desc": "근거를 들어 방법을 한 문장으로 말한다"}, {"label": "보통", "desc": "방법을 보여 주나 말로 잇지 못한다"}, {"label": "노력 요함", "desc": "답만 말하고 과정을 보이지 못한다"}]}]}'::jsonb,'{"잘함": "\"저는 여섯으로 시작했어요. 하나 더 주면 일곱이에요. 왜냐하면 배열판에서 여섯 다음 오른쪽이 일곱이니까요. 하나 먹으면 다섯이에요, 왼쪽으로 한 칸 가니까요.\"", "보통": "\"여섯이면 일곱이요. (하나 먹으면?) 음… 일곱이요?\" — 더 큰 수는 정확하나 작은 쪽에서 방향이 뒤집힘. 배열판은 짚음.", "노력 요함": "\"여섯… 여덟이요.\" 배열판을 짚지 않고 짐작으로 답하며, 어떻게 알았는지 설명하지 못함."}'::jsonb,'[{"text": "1만큼 큰/작은 방향을 반대로 잡지 않는가", "mis_code": "M07", "note": null}, {"text": "수 배열판이나 그림을 실제로 짚으며 세는가", "mis_code": "M06", "note": null}, {"text": "답을 말한 뒤 \"왜냐하면\"으로 근거를 잇는가", "mis_code": null, "note": "과정 중심"}]'::jsonb,'[2수01-02] 수의 순서','5차시(1만큼 더 큰 수·작은 수) 직후','M1-1-C5','photo','kedu')
  ON CONFLICT (code) DO UPDATE SET grade=EXCLUDED.grade, subject=EXCLUDED.subject, unit_code=EXCLUDED.unit_code, area=EXCLUDED.area, title=EXCLUDED.title, student_label=EXCLUDED.student_label, task_text=EXCLUDED.task_text, conditions=EXCLUDED.conditions, rubric=EXCLUDED.rubric, anchors=EXCLUDED.anchors, observe_points=EXCLUDED.observe_points, std_code=EXCLUDED.std_code, lesson_link=EXCLUDED.lesson_link, concept_code=EXCLUDED.concept_code, product_kind=EXCLUDED.product_kind, source=EXCLUDED.source, is_active=true;
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_06',1,'math','u1','글쓰기','0이 되는 순간','하나도 없을 때 — 0 이야기 만들기','무언가가 하나도 없어지는 이야기를 만들어요. 처음에는 몇 개였고, 나중에 0개가 되었는지 그림으로 그리고 글로 써 보세요. (예: 접시에 쿠키가 3개 있었는데 다 먹어서 0개가 되었어요.)',ARRAY['그림을 처음 장면과 나중 장면 두 칸으로 그리기','글에 처음 개수와 나중 개수(0)를 숫자로 쓰기','"0개", "하나도 없다"는 말을 글에 넣어 쓰기']::text[],'{"criteria": [{"name": "0의 의미", "levels": [{"label": "잘함", "desc": "아무것도 없는 상태를 0으로 바르게 나타낸다"}, {"label": "보통", "desc": "0을 쓰지만 \"없다\"는 말과 연결이 약하다"}, {"label": "노력 요함", "desc": "아무것도 없을 때 빈칸으로 두거나 1로 쓴다"}]}, {"name": "수 표현", "levels": [{"label": "잘함", "desc": "처음·나중 개수를 숫자로 정확히 쓴다"}, {"label": "보통", "desc": "한쪽 숫자만 쓴다"}, {"label": "노력 요함", "desc": "숫자 쓰기에 도움이 필요하다"}]}, {"name": "글쓰기", "levels": [{"label": "잘함", "desc": "두 문장으로 흐름이 이어지게 쓴다"}, {"label": "보통", "desc": "한 문장만 쓰거나 흐름이 끊긴다"}, {"label": "노력 요함", "desc": "낱말만 적고 문장으로 잇지 못한다"}]}]}'::jsonb,'{"잘함": "왼쪽 칸에 사탕 4개, 오른쪽 칸에 빈 접시. \"접시에 사탕이 4개 있었어요. 동생이랑 다 먹어서 0개가 되었어요. 하나도 없어요.\"", "보통": "두 칸을 그렸고 \"사탕 4개\"는 썼지만 나중 칸에 숫자를 쓰지 않고 접시만 비워 둠. 말로 물으면 \"없어요\"라고 답함.", "노력 요함": "그림은 한 칸만 그림. 빈 접시 아래에 1이라고 씀 — 아무것도 없는 상태를 수로 나타내는 데 도움이 필요함."}'::jsonb,'[{"text": "0을 수로 받아들이는가, \"수가 아니다\"라고 여기는가", "mis_code": "M08", "note": null}, {"text": "0과 1을 혼동하지 않는가", "mis_code": "M09", "note": null}, {"text": "그림의 빈 상태와 숫자 0을 스스로 연결하는가", "mis_code": null, "note": "표현-의미 연결"}]'::jsonb,'[2수01-01] 0과 9까지의 수','6차시(0의 개념) 직후','M1-1-C6','text','kedu')
  ON CONFLICT (code) DO UPDATE SET grade=EXCLUDED.grade, subject=EXCLUDED.subject, unit_code=EXCLUDED.unit_code, area=EXCLUDED.area, title=EXCLUDED.title, student_label=EXCLUDED.student_label, task_text=EXCLUDED.task_text, conditions=EXCLUDED.conditions, rubric=EXCLUDED.rubric, anchors=EXCLUDED.anchors, observe_points=EXCLUDED.observe_points, std_code=EXCLUDED.std_code, lesson_link=EXCLUDED.lesson_link, concept_code=EXCLUDED.concept_code, product_kind=EXCLUDED.product_kind, source=EXCLUDED.source, is_active=true;
INSERT INTO performance_tasks (code,grade,subject,unit_code,area,title,student_label,task_text,conditions,rubric,anchors,observe_points,std_code,lesson_link,concept_code,product_kind,source) VALUES ('수행과제_07',1,'math','u1','관찰·실험','짝지어 보면 알 수 있어요','누가 더 많을까 — 하나씩 짝지어요','두 가지 물건을 한 무리씩 모아요. (예: 블록과 색연필) 두 무리를 하나씩 짝지어 놓고, 어느 쪽이 더 많은지 알아보세요. 짝이 없는 것이 남은 쪽이 더 많은 쪽이에요. 사진을 찍고 말로 설명해 보세요.',ARRAY['두 무리의 개수를 9개 이하로 정하고, 각각 몇 개인지 세어 말하기','반드시 하나씩 짝지어 놓고 비교하기 (그냥 눈으로 보지 않기)','"○가 △보다 많아요 / 적어요" 문장으로 말하기']::text[],'{"criteria": [{"name": "비교 방법", "levels": [{"label": "잘함", "desc": "하나씩 짝지어(일대일 대응) 비교한다"}, {"label": "보통", "desc": "짝짓기를 하다 중간에 눈대중으로 바꾼다"}, {"label": "노력 요함", "desc": "늘어선 길이나 퍼진 정도로 판단한다"}]}, {"name": "세기 정확성", "levels": [{"label": "잘함", "desc": "두 무리 개수를 모두 정확히 센다"}, {"label": "보통", "desc": "한 무리에서 세기 오류가 있다"}, {"label": "노력 요함", "desc": "두 무리 모두 함께 세어야 한다"}]}, {"name": "많다·적다 표현", "levels": [{"label": "잘함", "desc": "두 표현을 문장으로 바르게 쓴다"}, {"label": "보통", "desc": "한쪽 표현만 쓰거나 한 번 뒤바꾼다"}, {"label": "노력 요함", "desc": "많다·적다를 반대로 쓴다"}]}]}'::jsonb,'{"잘함": "블록 7개와 색연필 5개를 위아래로 짝지어 놓고 사진. \"블록은 일곱 개, 색연필은 다섯 개예요. 짝을 지으니 블록 두 개가 남았어요. 그래서 블록이 색연필보다 많아요.\"", "보통": "짝을 지어 놓긴 했으나 개수를 셀 때 색연필을 하나 빠뜨림. \"블록이 더 많아요.\" — 결론은 맞으나 근거를 짝짓기로 설명하지 못하고 \"커 보여서요\"라고 답함.", "노력 요함": "색연필이 길게 늘어서 있어 \"색연필이 더 많아요\"라고 판단함. 짝을 지어 다시 보게 하면 스스로 고침."}'::jsonb,'[{"text": "개수가 아니라 늘어선 길이·퍼짐으로 비교하지 않는가", "mis_code": "M10", "note": null}, {"text": "많다·적다 말을 반대로 쓰지 않는가", "mis_code": "M11", "note": null}, {"text": "짝을 지어 남은 것을 근거로 결론을 말하는가", "mis_code": null, "note": "일대일 대응의 정착"}]'::jsonb,'[2수01-02] 수의 크기 비교','7차시(수의 크기 비교) 직후 — 단원 마무리 과제','M1-1-C7','photo','kedu')
